//! Standalone stage attribution. Compiling/linking is the coordinator's job.
//! Synthetic deltas exercise the encoder; they are not realtime execution proof.
use pine_runtime::*;
use pine_sema::analyze_source;
use pine_syntax::{Severity, SourceFile};
use serde_json::{Value, json};
use std::alloc::{GlobalAlloc, Layout, System};
use std::io::{self, Write};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;

struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
fn allocation(size: usize) {
    ALLOCATED.fetch_add(size, Relaxed);
    ALLOCS.fetch_add(1, Relaxed);
    let live = LIVE.fetch_add(size, Relaxed) + size;
    PEAK.fetch_max(live, Relaxed);
}
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(layout) };
        if !p.is_null() {
            allocation(layout.size());
        }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(p, layout) }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p, layout, size) };
        if !q.is_null() {
            LIVE.fetch_sub(layout.size(), Relaxed);
            allocation(size);
        }
        q
    }
}
#[global_allocator]
static GLOBAL: CountingAllocator = CountingAllocator;

#[derive(Clone, Copy)]
struct Stage {
    ms: f64,
    bytes: usize,
    count: usize,
    peak: usize,
    live_delta: i64,
}
fn measure<T>(f: impl FnOnce() -> T) -> (T, Stage) {
    let initial = LIVE.load(Relaxed);
    PEAK.store(initial, Relaxed);
    let bytes = ALLOCATED.load(Relaxed);
    let count = ALLOCS.load(Relaxed);
    let now = Instant::now();
    let result = std::hint::black_box(f());
    let ms = now.elapsed().as_secs_f64() * 1000.0;
    (
        result,
        Stage {
            ms,
            bytes: ALLOCATED.load(Relaxed) - bytes,
            count: ALLOCS.load(Relaxed) - count,
            peak: PEAK.load(Relaxed).saturating_sub(initial),
            live_delta: LIVE.load(Relaxed) as i64 - initial as i64,
        },
    )
}
fn stage_json(s: Stage) -> Value {
    json!({"ms":s.ms,"allocatedBytes":s.bytes,"allocations":s.count,
        "peakAdditionalLiveBytes":s.peak,"liveDeltaBytes":s.live_delta})
}

#[derive(Default)]
struct Counter {
    bytes: usize,
    writes: usize,
}
impl Write for Counter {
    fn write(&mut self, b: &[u8]) -> io::Result<usize> {
        let b = std::hint::black_box(b);
        self.bytes += b.len();
        self.writes += 1;
        Ok(b.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}
fn sample(pattern: &str, i: usize) -> f64 {
    match pattern {
        "ordinary" => 100.25 + (i % 17) as f64 / 16.0,
        "mixed" => [
            0.125,
            -17.75,
            1.0e20,
            -1.0e20,
            1.0e-20,
            -1.0e-20,
            f64::MIN_POSITIVE,
            f64::MAX,
            1.0000000000000002,
            -0.0,
        ][i % 10],
        "extreme" => 1.0e308,
        "subnormal" => 1.0e-310,
        "negative_zero" => -0.0,
        "nonfinite" => [f64::NAN, f64::INFINITY, f64::NEG_INFINITY, -0.0, 1.5][i % 5],
        "records" => [1.0e308, -1.0e308, 1.0e-310, -0.0, 17.25, f64::NAN][i % 6],
        _ => panic!("Unknown scenario"),
    }
}
fn bar(pattern: &str, i: usize) -> Bar {
    let x = sample(pattern, i);
    Bar {
        time: 1700000000 + i as i64 * 60,
        open: x,
        high: x,
        low: x,
        close: x,
        volume: 100.0,
    }
}
fn manual_result(pattern: &str, n: usize) -> RuntimeResult {
    let mut result = RuntimeResult::default();
    result.plots.push(PlotSeries::new(
        1,
        (0..n)
            .map(|i| PineValue::Float(sample(pattern, i)))
            .collect(),
    ));
    if pattern != "records" {
        return result;
    }
    let mut line = LineOutput {
        id: 2,
        snapshots: Vec::with_capacity(n),
    };
    let mut strategy = StrategyResult::default();
    for i in 0..n {
        let x = sample(pattern, i);
        line.snapshots.push(LineSnapshot {
            bar_index: i,
            exists: true,
            x1: PineValue::Int(i as i64),
            y1: PineValue::Float(x),
            x2: PineValue::Int(i as i64 + 1),
            y2: PineValue::Float(x),
            xloc: PineValue::String("xloc.bar_index".into()),
            color: PineValue::Na,
            width: PineValue::Int(1),
            style: PineValue::String("line.style_solid".into()),
            extend: PineValue::String("extend.none".into()),
        });
        strategy.orders.push(StrategyOrderEvent {
            id: "O\"\\\n汉🙂".into(),
            bar_index: i,
            time: i as i64,
            direction: "long".into(),
            qty: x,
            price: x,
        });
        strategy.trades.push(StrategyTrade {
            id: "T".into(),
            exit_id: "X".into(),
            entry_bar_index: i,
            exit_bar_index: i + 1,
            entry_time: i as i64,
            exit_time: i as i64 + 1,
            entry_price: x,
            exit_price: x,
            qty: x,
            profit: x,
        });
        strategy.position.push(StrategyPositionSnapshot {
            bar_index: i,
            size: x,
            avg_price: Some(x),
        });
        strategy.equity.push(StrategyEquitySnapshot {
            bar_index: i,
            cash: x,
            market_value: x,
            equity: x,
            net_profit: x,
        });
        strategy.alerts.push(StrategyOrderFillAlertOutput {
            id: "A".into(),
            bar_index: i,
            time: i as i64,
            direction: "strategy.exit".into(),
            qty: x,
            price: x,
            entry_id: Some("T".into()),
            exit_id: None,
            message: "\t\\\"汉🙂".into(),
        });
    }
    result.lines.push(line);
    result.strategy = Some(strategy);
    result.diagnostics.push(RuntimeDiagnostic {
        code: "E_PROBE".into(),
        message: "\0\n\t汉🙂".into(),
    });
    result
}
fn delta(result: &RuntimeResult, n: usize) -> RuntimeChanges {
    let mut c = RuntimeChanges::new(2, StreamingVisibility::Preview);
    for p in &result.plots {
        c.series.push(SeriesChange {
            family: SeriesFamily::Plot,
            id: p.id,
            op: SeriesChangeOp::Append,
            start: n,
            fields: SeriesFields {
                values: vec![p.values.last().unwrap().clone()],
                ..SeriesFields::default()
            },
            header: None,
        });
    }
    if let Some(line) = result.lines.first() {
        c.drawings.push(DrawingChange {
            family: DrawingFamily::Line,
            id: line.id,
            action: DrawingAction::SetTail {
                start: n - 1,
                object: DrawingObject::Line(LineOutput {
                    id: line.id,
                    snapshots: vec![line.snapshots.last().unwrap().clone()],
                }),
            },
        });
    }
    if let Some(s) = &result.strategy {
        c.strategy = Some(StrategyChanges {
            orders: Some(ListSplice {
                start: n - 1,
                items: vec![s.orders.last().unwrap().clone()],
            }),
            trades: Some(ListSplice {
                start: n - 1,
                items: vec![s.trades.last().unwrap().clone()],
            }),
            position: Some(ListSplice {
                start: n - 1,
                items: vec![s.position.last().unwrap().clone()],
            }),
            equity: Some(ListSplice {
                start: n - 1,
                items: vec![s.equity.last().unwrap().clone()],
            }),
            alerts: Some(ListSplice {
                start: n - 1,
                items: vec![s.alerts.last().unwrap().clone()],
            }),
            diagnostics: Some(result.diagnostics.clone()),
        });
    }
    c
}
#[derive(Default)]
struct Proof {
    finite: usize,
    null: usize,
    negative_zero: usize,
    digest: u64,
}
impl Proof {
    fn number(&mut self, value: &Value, expected: f64) {
        if expected.is_finite() {
            let got = value
                .as_f64()
                .expect("Finite numeric value became non-numeric");
            assert_eq!(
                got.to_bits(),
                expected.to_bits(),
                "float changed bits: {value}"
            );
            self.finite += 1;
            if expected.to_bits() == (-0.0f64).to_bits() {
                self.negative_zero += 1;
            }
            self.digest = self.digest.wrapping_mul(1099511628211) ^ expected.to_bits();
        } else {
            assert!(value.is_null(), "Nonfinite numeric output was not null");
            self.null += 1;
        }
    }
    fn pine(&mut self, value: &Value, expected: &PineValue) {
        match expected {
            PineValue::Float(x) => self.number(value, *x),
            PineValue::Int(x) => assert_eq!(value.as_i64(), Some(*x)),
            PineValue::Na => assert!(value.is_null()),
            _ => panic!("Unexpected numeric fixture type"),
        }
    }
}
fn prove_full(value: &Value, result: &RuntimeResult) -> Proof {
    let mut p = Proof::default();
    assert_eq!(
        value["schemaVersion"].as_u64(),
        Some(PUBLIC_RUNTIME_SCHEMA_VERSION as u64)
    );
    assert_eq!(value["plots"].as_array().unwrap().len(), result.plots.len());
    for (plot, expected) in value["plots"].as_array().unwrap().iter().zip(&result.plots) {
        let values = plot["values"].as_array().unwrap();
        assert_eq!(values.len(), expected.values.len());
        for (value, input) in values.iter().zip(&expected.values) {
            p.pine(value, input);
        }
    }
    assert_eq!(value["lines"].as_array().unwrap().len(), result.lines.len());
    for (line, expected) in value["lines"].as_array().unwrap().iter().zip(&result.lines) {
        let snapshots = line["snapshots"].as_array().unwrap();
        assert_eq!(snapshots.len(), expected.snapshots.len());
        for (v, input) in snapshots.iter().zip(&expected.snapshots) {
            p.pine(&v["y1"], &input.y1);
            p.pine(&v["y2"], &input.y2);
        }
    }
    if let Some(s) = &result.strategy {
        let v = &value["strategy"];
        assert_eq!(v["orders"].as_array().unwrap().len(), s.orders.len());
        assert_eq!(v["trades"].as_array().unwrap().len(), s.trades.len());
        assert_eq!(v["position"].as_array().unwrap().len(), s.position.len());
        assert_eq!(v["equity"].as_array().unwrap().len(), s.equity.len());
        assert_eq!(v["alerts"].as_array().unwrap().len(), s.alerts.len());
        for (v, x) in v["orders"].as_array().unwrap().iter().zip(&s.orders) {
            p.number(&v["qty"], x.qty);
            p.number(&v["price"], x.price);
        }
        for (v, x) in v["trades"].as_array().unwrap().iter().zip(&s.trades) {
            for (name, input) in [
                ("entryPrice", x.entry_price),
                ("exitPrice", x.exit_price),
                ("qty", x.qty),
                ("profit", x.profit),
            ] {
                p.number(&v[name], input);
            }
        }
        for (v, x) in v["position"].as_array().unwrap().iter().zip(&s.position) {
            p.number(&v["size"], x.size);
            p.number(&v["avgPrice"], x.avg_price.unwrap());
        }
        for (v, x) in v["equity"].as_array().unwrap().iter().zip(&s.equity) {
            for (name, input) in [
                ("cash", x.cash),
                ("marketValue", x.market_value),
                ("equity", x.equity),
                ("netProfit", x.net_profit),
            ] {
                p.number(&v[name], input);
            }
        }
        for (v, x) in v["alerts"].as_array().unwrap().iter().zip(&s.alerts) {
            p.number(&v["qty"], x.qty);
            p.number(&v["price"], x.price);
        }
    }
    p
}
fn proof_json(p: Proof) -> Value {
    json!({"finiteFloatBitsChecked":p.finite,"nonfiniteNullsChecked":p.null,
    "negativeZeroBitsChecked":p.negative_zero,"inputBitsFnv64":format!("{:016x}",p.digest)})
}
fn parsed_pine_bits(value: &PineValue) -> Option<u64> {
    match value {
        PineValue::Float(x) => Some(x.to_bits()),
        PineValue::Int(x) => Some((*x as f64).to_bits()),
        PineValue::Color(x) => Some((*x as f64).to_bits()),
        PineValue::Na => None,
        _ => panic!("Invalid public numeric parse"),
    }
}
fn public_parse_proof(parsed: &RuntimeResult, expected: &RuntimeResult) {
    assert_eq!(parsed.plots.len(), expected.plots.len());
    for (got, want) in parsed.plots.iter().zip(&expected.plots) {
        assert_eq!(got.values.len(), want.values.len());
        for (got, want) in got.values.iter().zip(&want.values) {
            let expected = match want {
                PineValue::Float(x) if x.is_finite() => Some(x.to_bits()),
                PineValue::Float(_) | PineValue::Na => None,
                _ => parsed_pine_bits(want),
            };
            assert_eq!(
                parsed_pine_bits(got),
                expected,
                "Public parser changed float bits"
            );
        }
    }
    // Preserve every record/drawing numeric bit as well as plot values. The
    // public parser may normalize integer-vs-float representation, which has no
    // effect on the public numeric token's f64 bits.
    let mut bytes = Vec::new();
    write_public_runtime_result_json(parsed, &mut bytes).unwrap();
    prove_full(&serde_json::from_slice::<Value>(&bytes).unwrap(), expected);
}
fn prove_delta(value: &Value, expected: &RuntimeChanges) -> Proof {
    let mut p = Proof::default();
    assert_eq!(
        value["series"].as_array().unwrap().len(),
        expected.series.len()
    );
    for (v, want) in value["series"]
        .as_array()
        .unwrap()
        .iter()
        .zip(&expected.series)
    {
        let values = v["values"].as_array().unwrap();
        assert_eq!(values.len(), want.fields.values.len());
        for (v, want) in values.iter().zip(&want.fields.values) {
            p.pine(v, want);
        }
    }
    assert_eq!(
        value["drawings"].as_array().unwrap().len(),
        expected.drawings.len()
    );
    for (v, want) in value["drawings"]
        .as_array()
        .unwrap()
        .iter()
        .zip(&expected.drawings)
    {
        if let DrawingAction::SetTail {
            object: DrawingObject::Line(line),
            ..
        } = &want.action
        {
            let snapshots = v["object"]["snapshots"].as_array().unwrap();
            assert_eq!(snapshots.len(), line.snapshots.len());
            for (v, want) in snapshots.iter().zip(&line.snapshots) {
                p.pine(&v["y1"], &want.y1);
                p.pine(&v["y2"], &want.y2);
            }
        } else {
            panic!("Unknown drawing fixture");
        }
    }
    if let Some(s) = &expected.strategy {
        let v = &value["strategy"];
        let orders = &s.orders.as_ref().unwrap().items;
        let trades = &s.trades.as_ref().unwrap().items;
        let position = &s.position.as_ref().unwrap().items;
        let equity = &s.equity.as_ref().unwrap().items;
        let alerts = &s.alerts.as_ref().unwrap().items;
        for (name, length) in [
            ("orders", orders.len()),
            ("trades", trades.len()),
            ("position", position.len()),
            ("equity", equity.len()),
            ("alerts", alerts.len()),
        ] {
            assert_eq!(v[name]["items"].as_array().unwrap().len(), length);
        }
        for (v, x) in v["orders"]["items"].as_array().unwrap().iter().zip(orders) {
            p.number(&v["qty"], x.qty);
            p.number(&v["price"], x.price);
        }
        for (v, x) in v["trades"]["items"].as_array().unwrap().iter().zip(trades) {
            for (name, input) in [
                ("entryPrice", x.entry_price),
                ("exitPrice", x.exit_price),
                ("qty", x.qty),
                ("profit", x.profit),
            ] {
                p.number(&v[name], input);
            }
        }
        for (v, x) in v["position"]["items"]
            .as_array()
            .unwrap()
            .iter()
            .zip(position)
        {
            p.number(&v["size"], x.size);
            p.number(&v["avgPrice"], x.avg_price.unwrap());
        }
        for (v, x) in v["equity"]["items"].as_array().unwrap().iter().zip(equity) {
            for (name, input) in [
                ("cash", x.cash),
                ("marketValue", x.market_value),
                ("equity", x.equity),
                ("netProfit", x.net_profit),
            ] {
                p.number(&v[name], input);
            }
        }
        for (v, x) in v["alerts"]["items"].as_array().unwrap().iter().zip(alerts) {
            p.number(&v["qty"], x.qty);
            p.number(&v["price"], x.price);
        }
    }
    p
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = std::env::args().collect();
    if args.len() != 5 {
        return Err("usage: serialization_probe SCENARIO BARS SOURCE OUTPUT_DIRECTORY".into());
    }
    let pattern = &args[1];
    let n: usize = args[2].parse()?;
    assert!(n > 0);
    let output = std::path::Path::new(&args[4]);
    std::fs::create_dir_all(output)?;
    let manual = matches!(pattern.as_str(), "negative_zero" | "nonfinite" | "records");
    let text = std::fs::read_to_string(&args[3])?;
    let source = SourceFile::new("serialization-probe.pine", text);
    let (analysis, parse_stage) = measure(|| analyze_source(&source));
    if analysis
        .diagnostics
        .iter()
        .any(|d| d.severity == Severity::Error)
    {
        return Err(format!("{:?}", analysis.diagnostics).into());
    }
    let hir = analysis.hir.ok_or("no HIR")?;
    let mut runtime = HistoricalRuntime::new(&hir);
    let (_, seed_stage) = measure(|| {
        if !manual {
            for i in 0..n {
                runtime.append_bar(bar(pattern, i)).unwrap();
            }
        }
    });
    let (result, result_stage) = measure(|| {
        if manual {
            manual_result(pattern, n)
        } else {
            runtime.result()
        }
    });
    assert_eq!(result.plots.len(), 1);
    assert_eq!(result.plots[0].values.len(), n);
    for (i, value) in result.plots[0].values.iter().enumerate() {
        let expected = sample(pattern, i);
        if expected.is_finite() {
            assert_eq!(
                parsed_pine_bits(value),
                Some(expected.to_bits()),
                "Fixture differs from direct input bits"
            );
        }
    }
    let (view, view_stage) = measure(|| {
        if manual {
            result.view()
        } else {
            runtime.result_view()
        }
    });
    let (c, delta_stage) = measure(|| delta(&result, n));
    let (owned_sink, s_owned_sink) = measure(|| {
        let mut sink = Counter::default();
        write_public_runtime_result_json(&result, &mut sink).unwrap();
        sink
    });
    let (view_sink, s_view_sink) = measure(|| {
        let mut sink = Counter::default();
        write_public_runtime_result_view_json(&view, &mut sink).unwrap();
        sink
    });
    let (bytes, s_owned_vec) = measure(|| {
        let mut v = Vec::new();
        write_public_runtime_result_json(&result, &mut v).unwrap();
        v
    });
    let full_bytes = bytes.len();
    assert_eq!(owned_sink.bytes, full_bytes);
    assert_eq!(view_sink.bytes, full_bytes);
    let (view_bytes, s_view_vec) = measure(|| {
        let mut v = Vec::new();
        write_public_runtime_result_view_json(&view, &mut v).unwrap();
        v
    });
    assert_eq!(bytes, view_bytes);
    drop(view_bytes);
    let (string, s_owned_string) = measure(|| public_runtime_result_json(&result));
    assert_eq!(bytes, string.as_bytes());
    drop(string);
    let (string, s_view_string) = measure(|| public_runtime_result_view_json(&view));
    assert_eq!(bytes, string.as_bytes());
    drop(string);
    let (owned_copy, s_owned_copy) = measure(|| result.clone());
    let (string, s_consume) = measure(|| into_public_runtime_result_json(owned_copy));
    assert_eq!(bytes, string.as_bytes());
    drop(string);
    let (delta_sink, s_delta_sink) = measure(|| {
        let mut sink = Counter::default();
        write_public_runtime_changes_json(&c, &mut sink).unwrap();
        sink
    });
    let (delta_bytes, s_delta_vec) = measure(|| {
        let mut v = Vec::new();
        write_public_runtime_changes_json(&c, &mut v).unwrap();
        v
    });
    assert_eq!(delta_sink.bytes, delta_bytes.len());
    let (string, s_delta_string) = measure(|| public_runtime_changes_json(&c));
    assert_eq!(delta_bytes, string.as_bytes());
    drop(string);
    let (parsed, s_json_parse) = measure(|| serde_json::from_slice::<Value>(&bytes).unwrap());
    let proof = prove_full(&parsed, &result);
    drop(parsed);
    let (public, s_public_parse) =
        measure(|| runtime_result_from_json(std::str::from_utf8(&bytes).unwrap()).unwrap());
    public_parse_proof(&public, &result);
    drop(public);
    let (parsed, s_delta_json_parse) =
        measure(|| serde_json::from_slice::<Value>(&delta_bytes).unwrap());
    let delta_proof = prove_delta(&parsed, &c);
    drop(parsed);
    let (public, s_delta_public_parse) =
        measure(|| runtime_changes_from_json(std::str::from_utf8(&delta_bytes).unwrap()).unwrap());
    assert_eq!(public.series.len(), c.series.len());
    for (got, want) in public.series.iter().zip(&c.series) {
        let expected = match &want.fields.values[0] {
            PineValue::Float(x) if x.is_finite() => Some(x.to_bits()),
            _ => None,
        };
        assert_eq!(parsed_pine_bits(&got.fields.values[0]), expected);
    }
    let mut public_bytes = Vec::new();
    write_public_runtime_changes_json(&public, &mut public_bytes).unwrap();
    prove_delta(&serde_json::from_slice::<Value>(&public_bytes).unwrap(), &c);
    drop(public);
    std::fs::write(output.join("full.json"), &bytes)?;
    std::fs::write(output.join("delta.json"), &delta_bytes)?;
    println!(
        "{}",
        json!({"schemaVersion":1,"scenario":pattern,"bars":n,"manualFixture":manual,
        "deltaFixture":"synthetic append-one-point encoder fixture; not runtime update qualification",
        "fullBytes":full_bytes,"deltaBytes":delta_bytes.len(),"fullProof":proof_json(proof),"deltaProof":proof_json(delta_proof),
        "sinkWriteCalls":{"owned":owned_sink.writes,"view":view_sink.writes,"delta":delta_sink.writes},
        "byteEquality":{"ownedView":true,"ownedString":true,"viewString":true,"consumedString":true,"deltaString":true},
        "stages":{"parseAnalyze":stage_json(parse_stage),"seed":stage_json(seed_stage),
            "resultMaterialization":stage_json(result_stage),"viewConstruction":stage_json(view_stage),"deltaConstruction":stage_json(delta_stage),
            "ownedSink":stage_json(s_owned_sink),"viewSink":stage_json(s_view_sink),"ownedVec":stage_json(s_owned_vec),"viewVec":stage_json(s_view_vec),
            "ownedString":stage_json(s_owned_string),"viewString":stage_json(s_view_string),"consumedSourceClone":stage_json(s_owned_copy),"consumedString":stage_json(s_consume),
            "deltaSink":stage_json(s_delta_sink),"deltaVec":stage_json(s_delta_vec),"deltaString":stage_json(s_delta_string),
            "jsonParse":stage_json(s_json_parse),"publicParse":stage_json(s_public_parse),
            "deltaJsonParse":stage_json(s_delta_json_parse),"deltaPublicParse":stage_json(s_delta_public_parse)}})
    );
    Ok(())
}

serialization_runner.py.text:
"""Focused serialization stage receipts; never builds or links a probe.

One fresh process per scenario/version/repetition, alternating before/after.
Both raw output objects and subprocess receipts are retained independently.
"""
from __future__ import annotations
import argparse
from datetime import datetime, timezone
import hashlib
import json
import math
from pathlib import Path
import statistics
import struct
import subprocess
import time
import uuid

D = Path(__file__).resolve().parent
ROOT = D.parents[1]
STAGES = {
    "parseAnalyze", "seed", "resultMaterialization", "viewConstruction", "deltaConstruction",
    "ownedSink", "viewSink", "ownedVec", "viewVec", "ownedString", "viewString",
    "consumedSourceClone", "consumedString", "deltaSink", "deltaVec", "deltaString",
    "jsonParse", "publicParse", "deltaJsonParse", "deltaPublicParse",
}
FIELDS = {"ms", "allocatedBytes", "allocations", "peakAdditionalLiveBytes", "liveDeltaBytes"}
TOP = {"schemaVersion", "scenario", "bars", "manualFixture", "deltaFixture", "fullBytes",
       "deltaBytes", "fullProof", "deltaProof", "sinkWriteCalls", "byteEquality", "stages"}

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def save(path, value):
    path = Path(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, ensure_ascii=False, allow_nan=False, indent=2), encoding="utf8")
    tmp.replace(path)

def pairs(items):
    value = {}
    for key, item in items:
        if key in value:
            raise ValueError("Duplicate JSON field: " + key)
        value[key] = item
    return value

def constant(token):
    raise ValueError("Nonfinite JSON token: " + token)

def scalar_int(token):
    # JSON's -0 token is integral lexically but carries a float sign on the wire.
    return -0.0 if token == "-0" else int(token)

def scalar_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError("Out-of-f64-range JSON number: " + token)
    return value

def loads(raw):
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant,
                      parse_int=scalar_int, parse_float=scalar_float)

def read(path):
    return loads(Path(path).read_text(encoding="utf-8-sig"))

def identity(tag, probe="serialization"):
    path = D / f"identity-{probe}-{tag}.json"
    link = read(path)
    binary = D / f"{probe}-{tag}.exe"
    source = D / f"{probe}_probe.rs"
    if sha(binary) != link["executableSha256"] or sha(source) != link["sourceSha256"]:
        raise ValueError("Serialization binary/source identity mismatch: " + tag)
    # Every linked library must be found at its recorded path or archived receipt.
    archive = read(D / "before-binary-identity.json") if tag == "before" else None
    for rawpath, expected in link["libraryHashes"].items():
        direct = Path(rawpath)
        direct = direct if direct.is_absolute() else ROOT / direct
        alternatives = [direct]
        if archive is not None:
            for key, item in archive["libraries"].items():
                if item["sha256"] == expected and (key == rawpath or Path(key).name == direct.name):
                    alternatives.append(Path(item["archive"]))
        if not any(p.exists() and sha(p) == expected for p in alternatives):
            raise ValueError("Linked library identity mismatch: " + rawpath)
    return {"binary":str(binary), "binarySha256":sha(binary), "sourceSha256":sha(source),
            "linkReceipt":str(path), "linkReceiptSha256":sha(path), "link":link}

def plan():
    return [
        {"name":"ordinary100k", "scenario":"ordinary", "bars":100000},
        {"name":"mixed20k", "scenario":"mixed", "bars":20000},
        {"name":"extreme20k", "scenario":"extreme", "bars":20000},
        {"name":"subnormal20k", "scenario":"subnormal", "bars":20000},
        {"name":"negative_zero20k", "scenario":"negative_zero", "bars":20000},
        {"name":"nonfinite20k", "scenario":"nonfinite", "bars":20000},
        {"name":"records4003", "scenario":"records", "bars":4003},
    ]

def prepare():
    source = D / "serialization-source.pine"
    text = '//@version=6\nindicator("serialization attribution")\nplot(close)\n'
    if source.exists() and source.read_text(encoding="utf8") != text:
        raise ValueError("Prepared source differs")
    if not source.exists():
        source.write_text(text, encoding="utf8")
    receipt = {"cases":plan(), "source":{"path":str(source), "sha256":sha(source)},
               "repetitionsPerVersion":3, "plannedProcesses":42, "probesExecuted":False,
               "scope":"Focused serialization stages, not full resource qualification"}
    save(D / "serialization-plan.json", receipt)
    return receipt

def integer(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("Expected integer metric")
    return value

def metrics(raw, case):
    lines = raw.splitlines()
    if len(lines) != 1 or not lines[0]:
        raise ValueError("Expected one metrics JSON line")
    result = loads(lines[0])
    if not isinstance(result, dict) or set(result) != TOP:
        raise ValueError("Unknown/missing top-level metrics field")
    if result["schemaVersion"] != 1 or result["scenario"] != case["scenario"] or result["bars"] != case["bars"]:
        raise ValueError("Metrics scenario/bars/schema mismatch")
    if result["manualFixture"] is not (case["scenario"] in {"negative_zero", "nonfinite", "records"}):
        raise ValueError("Metrics fixture classification differs")
    for field in ("fullBytes", "deltaBytes"):
        if integer(result[field]) <= 0:
            raise ValueError("Empty serialized object")
    if set(result["stages"]) != STAGES:
        raise ValueError("Unknown/missing stage")
    for name, stage in result["stages"].items():
        if set(stage) != FIELDS:
            raise ValueError("Unknown/missing stage metric: " + name)
        for key, value in stage.items():
            if isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value):
                raise ValueError("Nonfinite/nonnumeric stage metric")
            if key != "ms":
                integer(value)
            if key != "liveDeltaBytes" and value < 0:
                raise ValueError("Negative unsigned stage metric")
    if set(result["byteEquality"]) != {"ownedView", "ownedString", "viewString", "consumedString", "deltaString"}:
        raise ValueError("Missing byte proof")
    if not all(value is True for value in result["byteEquality"].values()):
        raise ValueError("Byte equality did not pass")
    for field in ("fullProof", "deltaProof"):
        proof = result[field]
        if set(proof) != {"finiteFloatBitsChecked", "nonfiniteNullsChecked", "negativeZeroBitsChecked", "inputBitsFnv64"}:
            raise ValueError("Malformed input-bit proof")
        for key in ("finiteFloatBitsChecked", "nonfiniteNullsChecked", "negativeZeroBitsChecked"):
            if integer(proof[key]) < 0:
                raise ValueError("Negative proof count")
        digest = proof["inputBitsFnv64"]
        if not isinstance(digest, str) or len(digest) != 16 or any(c not in "0123456789abcdef" for c in digest):
            raise ValueError("Invalid direct-input digest")
    return result

def equivalent(a, b, path="$"):
    # Integer identifiers remain exact. Float/integer lexical conversions are
    # compared as IEEE f64; the Rust probe separately checks original f64 bits.
    if isinstance(a, bool) or isinstance(b, bool):
        if type(a) is not type(b) or a != b:
            raise ValueError("Boolean differs at " + path)
    elif isinstance(a, (float, int)) and isinstance(b, (float, int)):
        if isinstance(a, int) and isinstance(b, int):
            if a != b:
                raise ValueError("Integer differs at " + path)
        elif struct.pack("!d", float(a)) != struct.pack("!d", float(b)):
            raise ValueError("Float bits differ at " + path)
    elif isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys():
            raise ValueError("Object keys differ at " + path)
        for key in a:
            equivalent(a[key], b[key], path + "." + key)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            raise ValueError("Array length differs at " + path)
        for i, (x, y) in enumerate(zip(a, b)):
            equivalent(x, y, path + f"[{i}]")
    elif type(a) is not type(b) or a != b:
        raise ValueError("Non-numeric field differs at " + path)

def run(out, stem, command, timeout):
    start = time.monotonic()
    try:
        p = subprocess.run(command, cwd=ROOT, capture_output=True, timeout=timeout)
        stdout, stderr, code = p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired as error:
        stdout, stderr, code = error.stdout or b"", error.stderr or b"", None
    o, e, x = (out / (stem + suffix) for suffix in (".stdout", ".stderr", ".exit.json"))
    o.write_bytes(stdout); e.write_bytes(stderr)
    save(x, {"command":command, "returncode":code, "timeoutSeconds":timeout if code is None else None})
    return {"command":command, "returncode":code, "wallSeconds":time.monotonic()-start,
            "stdout":str(o), "stdoutSha256":sha(o), "stderr":str(e), "stderrSha256":sha(e),
            "exit":str(x), "exitSha256":sha(x)}, stdout

def correctness_gates():
    result = {}
    for tag in ("windows", "linux"):
        p = D / f"gate-{tag}.exit"
        if int(p.read_text(encoding="utf-8-sig")) != 0:
            raise ValueError("Full gate did not pass: " + tag)
        result[tag] = {"exitSha256":sha(p), "logSha256":sha(D / f"gate-{tag}.log")}
    ordinary = read(D / "ordinary-results.json")
    if ordinary["status"] != "passed":
        raise ValueError("Ordinary byte comparison must pass first")
    text = subprocess.check_output(["powershell.exe", "-NoProfile", "-Command",
        'Get-Process | Where-Object { $_.ProcessName -match "^(cargo|rustc|maturin|link|cl|msbuild|pine.*)$" } | Select-Object ProcessName,Id | ConvertTo-Json']).decode("utf8").strip()
    if text:
        raise ValueError("Build/validation process still active: " + text)
    return {"gates":result, "ordinarySha256":sha(D / "ordinary-results.json"),
            "matchingWindowsBuildProcesses":[],
            "limitation":"Coordinator also keeps WSL compilation and other measurements quiescent; this does not prove OS inactivity."}

def summarize(cases, records):
    summary = {}
    for case in cases:
        by_tag = {tag:[r for r in records if r["case"] == case["name"] and r["tag"] == tag] for tag in ("before", "after")}
        if any(len(v) != 3 for v in by_tag.values()):
            raise ValueError("Incomplete repetition set")
        all_rows = by_tag["before"] + by_tag["after"]
        proof = all_rows[0]["metrics"]["fullProof"]
        delta_proof = all_rows[0]["metrics"]["deltaProof"]
        for row in all_rows:
            if row["metrics"]["fullProof"] != proof or row["metrics"]["deltaProof"] != delta_proof:
                raise ValueError("Input semantic proof differs between versions/repetitions")
        stages = {}
        for stage in sorted(STAGES):
            stages[stage] = {}
            for metric in sorted(FIELDS):
                b = [r["metrics"]["stages"][stage][metric] for r in by_tag["before"]]
                a = [r["metrics"]["stages"][stage][metric] for r in by_tag["after"]]
                bm, am = statistics.median(b), statistics.median(a)
                stages[stage][metric] = {"beforeSamples":b, "afterSamples":a,
                    "beforeMedian":bm, "afterMedian":am, "afterBeforeRatio":am/bm if bm else None}
        size = {key:{tag:[r["metrics"][key] for r in by_tag[tag]] for tag in by_tag} for key in ("fullBytes", "deltaBytes")}
        summary[case["name"]] = {"scenario":case["scenario"], "bars":case["bars"],
            "stages":stages, "serializedBytes":size, "fullProof":proof, "deltaProof":delta_proof}
    return summary

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--prepare-only", action="store_true")
    ap.add_argument("--timeout", type=float, default=300)
    args = ap.parse_args()
    prepared = prepare()
    if args.prepare_only:
        print("Prepared 7 cases / 42 processes; no builds or probes executed.")
        return
    quiet = correctness_gates()
    identities = {tag:identity(tag) for tag in ("before", "after")}
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ") + "-" + uuid.uuid4().hex[:8]
    out = D / "serialization-receipts" / stamp
    out.mkdir(parents=True, exist_ok=False)
    receipt = {"status":"running", "plannedProcesses":42, "method":"7 focused cases, 3 fresh processes per version, alternating before/after order",
        "quiescence":quiet, "identities":identities, "runnerSha256":sha(Path(__file__)),
        "cases":prepared["cases"], "source":prepared["source"], "records":[],
        "limits":["Requested allocation sizes exclude allocator overhead; no whole-process peak claim.",
                  "Synthetic delta is an encoder fixture, not realtime execution proof.",
                  "Manual fixture result materialization includes fixture creation; seed is deliberately empty.",
                  "Raw JSON bytes are saved after measurement; output and JSON parse heaps are attributed separately.",
                  "Descriptive three-sample medians, not full-resource qualification."]}
    try:
        for repetition in range(3):
            for case in prepared["cases"]:
                pair = {}
                for tag in (("before", "after") if repetition % 2 == 0 else ("after", "before")):
                    stem = f'{case["name"]}-{tag}-{repetition}'
                    rawdir = out / stem
                    command = [identities[tag]["binary"], case["scenario"], str(case["bars"]), prepared["source"]["path"], str(rawdir)]
                    run_receipt, raw = run(out, stem, command, args.timeout)
                    row = {"case":case["name"], "tag":tag, "repetition":repetition, "run":run_receipt}
                    receipt["records"].append(row); save(out / "progress.json", receipt)
                    if run_receipt["returncode"] != 0:
                        raise RuntimeError("Serialization process failed: " + stem)
                    row["metrics"] = metrics(raw, case)
                    row["rawJson"] = {}
                    for kind in ("full", "delta"):
                        path = rawdir / (kind + ".json")
                        raw_json = path.read_bytes()
                        if len(raw_json) != row["metrics"][kind + "Bytes"]:
                            raise ValueError("Recorded JSON length differs")
                        loads(raw_json) # strict duplicate/nonfinite rejection
                        row["rawJson"][kind] = {"path":str(path), "sha256":sha(path), "bytes":len(raw_json)}
                    pair[tag] = row
                    save(out / "progress.json", receipt)
                    print(stem, "fullBytes", row["metrics"]["fullBytes"], "ownedSinkMs", row["metrics"]["stages"]["ownedSink"]["ms"], flush=True)
                for kind in ("full", "delta"):
                    b = Path(pair["before"]["rawJson"][kind]["path"]).read_bytes()
                    a = Path(pair["after"]["rawJson"][kind]["path"]).read_bytes()
                    equivalent(loads(b), loads(a))
                    pair["after"].setdefault("beforeComparison", {})[kind] = {"sameBytes":a == b,
                        "sameNumericBitsAndStructure":True, "lexicalChangeOnly":a != b,
                        "beforeSha256":hashlib.sha256(b).hexdigest(), "afterSha256":hashlib.sha256(a).hexdigest()}
                save(out / "progress.json", receipt)
        for tag in identities:
            if identity(tag) != identities[tag]:
                raise ValueError("Linked identity changed")
        if sha(prepared["source"]["path"]) != prepared["source"]["sha256"]:
            raise ValueError("Source changed")
        receipt.update(status="passed", completedProcesses=42, summary=summarize(prepared["cases"], receipt["records"]))
        save(out / "summary.json", receipt); save(D / "serialization-results.json", receipt)
        print("PASS 7 cases / 42 processes", flush=True)
    except BaseException as error:
        receipt.update(status="failed", error=repr(error), completedProcesses=len(receipt["records"]))
        save(out / "failure.json", receipt); save(out / "progress.json", receipt)
        raise

if __name__ == "__main__":
    main()

heap_probe.rs.text:
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
use std::time::Instant;
use pine_runtime::{Bar, BarUpdate, HistoricalRuntime, RealtimeRuntime, OutputRetention};
use pine_sema::analyze_source;
use pine_syntax::{SourceFile, Severity};
use serde_json::json;

struct CountingAllocator;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static ALLOCATED: AtomicUsize = AtomicUsize::new(0);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let p = unsafe { System.alloc(layout) };
        if !p.is_null() { LIVE.fetch_add(layout.size(), Relaxed); ALLOCATED.fetch_add(layout.size(), Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        p
    }
    unsafe fn dealloc(&self, p: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Relaxed);
        unsafe { System.dealloc(p, layout) }
    }
    unsafe fn realloc(&self, p: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        let q = unsafe { System.realloc(p, layout, size) };
        if !q.is_null() { LIVE.fetch_add(size, Relaxed); LIVE.fetch_sub(layout.size(), Relaxed); ALLOCATED.fetch_add(size, Relaxed); ALLOCS.fetch_add(1, Relaxed); }
        q
    }
}
#[global_allocator] static GLOBAL: CountingAllocator = CountingAllocator;
fn bar(i: usize) -> Bar { let x=100.0+(i%17) as f64/16.0; Bar {time:1700000000+i as i64*60,open:x, high:x+1.0,low:x-1.0,close:x+0.25,volume:100.0} }
fn median(v: &mut [f64]) -> f64 {v.sort_by(f64::total_cmp); v[v.len()/2]}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    let source_text = std::fs::read_to_string(&args[1])?;
    let n: usize = args[2].parse()?;
    let mode=args.get(3).map(String::as_str).unwrap_or("historical");
    let source=SourceFile::new("probe.pine",source_text);
    let analysis=analyze_source(&source);
    if analysis.diagnostics.iter().any(|d|d.severity==Severity::Error) {return Err(format!("{:?}", analysis.diagnostics).into());}
    let hir=analysis.hir.ok_or("no hir")?;
    let initial=LIVE.load(Relaxed);
    if mode=="historical" {
        let mut runtime=HistoricalRuntime::new(&hir);
        let initial_allocated=ALLOCATED.load(Relaxed);
        let initial_allocations=ALLOCS.load(Relaxed);
        let started=Instant::now();
        for i in 0..n {runtime.append_bar(bar(i)).map_err(|e|e.message)?;}
        let seed_ms=started.elapsed().as_secs_f64()*1000.0;
        let seed_allocated=ALLOCATED.load(Relaxed)-initial_allocated;
        let seed_allocations=ALLOCS.load(Relaxed)-initial_allocations;
        let retained=LIVE.load(Relaxed)-initial;
        let profile=runtime.profile();
        let mut times=[0.0;31]; let mut clone_bytes=0; let mut clone_allocs=0;
        for t in &mut times {let live=LIVE.load(Relaxed); let count=ALLOCS.load(Relaxed); let started=Instant::now(); let copy=std::hint::black_box(runtime.clone()); *t=started.elapsed().as_secs_f64()*1000.0; clone_bytes=LIVE.load(Relaxed)-live;clone_allocs=ALLOCS.load(Relaxed)-count;drop(copy);}
        let live=LIVE.load(Relaxed); let started=Instant::now(); let result=runtime.result(); let result_ms=started.elapsed().as_secs_f64()*1000.0; let result_bytes=LIVE.load(Relaxed)-live;
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"seedMs":seed_ms,"seedAllocatedBytes":seed_allocated,"seedAllocations":seed_allocations,"rollingWindowValues":profile.rolling_window_values,"rollingWindowValueCapacity":profile.rolling_window_value_capacity,"seriesValues":profile.series_values,"matrixSlots":profile.matrix_slots,"matrixCells":profile.matrix_cells,"arraySlots":profile.array_slots,"arrayValues":profile.array_values,"cloneHeapBytes":clone_bytes,"cloneAllocations":clone_allocs,"cloneMedianMs":median(&mut times),"resultHeapBytes":result_bytes,"resultMs":result_ms,"plotValues":profile.plot_values}));
        std::hint::black_box(result);
    } else {
        let mut runtime=RealtimeRuntime::new(&hir);
        if mode=="retained" {runtime.set_output_retention(OutputRetention::keep_confirmed_bars(64));}
        let bars:Vec<_>=(0..n).map(bar).collect();
        drop(runtime.seed_historical(&bars).map_err(|e|e.message)?);drop(bars);
        let retained=LIVE.load(Relaxed)-initial;
        let mut diff_ms=[0.0;31]; let mut diff_bytes=[0usize;31];
        let mut full_ms=[0.0;31]; let mut full_bytes=[0usize;31];
        for i in 0..31 {
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let changes=runtime.apply_update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?; diff_ms[i]=start.elapsed().as_secs_f64()*1000.0;diff_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(changes);
            let prior=ALLOCATED.load(Relaxed);let start=Instant::now();let result=runtime.update(BarUpdate::forming(bar(n))).map_err(|e|e.message)?;full_ms[i]=start.elapsed().as_secs_f64()*1000.0;full_bytes[i]=ALLOCATED.load(Relaxed)-prior;drop(result);
        }
        diff_bytes.sort();full_bytes.sort();
        println!("{}",json!({"mode":mode,"bars":n,"script":args[1],"retainedHeapBytes":retained,"applyUpdateMedianMs":median(&mut diff_ms),"updateMedianMs":median(&mut full_ms),"applyAllocatedMedianBytes":diff_bytes[15],"updateAllocatedMedianBytes":full_bytes[15],"seriesValues":runtime.profile().series_values,"matrixSlots":runtime.profile().matrix_slots}));
    }
    Ok(())
}

