use pine_runtime::{Bar, BarUpdate, RealtimeRuntime, RuntimeResult, OutputRetention, write_public_runtime_result_json};
use pine_sema::analyze_source;
use pine_syntax::{SourceFile, Severity};
use std::io::Write;
fn bar(i:usize, offset:f64)->Bar { let x=100.0+(i%17) as f64/16.0; Bar {time:1700000000+i as i64*60,open:x,high:x+2.0,low:x-2.0,close:x+offset,volume:100.0} }
fn bytes(r:&RuntimeResult)->Vec<u8> {let mut b=Vec::new();write_public_runtime_result_json(r,&mut b).unwrap();b}
fn snapshot(runtime:&RealtimeRuntime<'_>)->Vec<u8> {
 let owned=bytes(&runtime.result());
 #[cfg(borrowed_result)] {
  let mut view=Vec::new();
  pine_runtime::write_public_runtime_result_view_json(&runtime.result_view(),&mut view).unwrap();
  assert_eq!(owned,view,"borrowed full snapshot differs");
  let mut confirmed=Vec::new();
  pine_runtime::write_public_runtime_result_view_json(&runtime.confirmed_result_view(),&mut confirmed).unwrap();
  assert_eq!(bytes(&runtime.confirmed_result()),confirmed,"borrowed confirmed snapshot differs");
 }
 owned
}
fn main()->Result<(),Box<dyn std::error::Error>> {
 let args:Vec<_>=std::env::args().collect();
 let source=SourceFile::new("probe.pine",std::fs::read_to_string(&args[1])?);
 let analysis=analyze_source(&source);
 if analysis.diagnostics.iter().any(|d|d.severity==Severity::Error) {return Err(format!("{:?}",analysis.diagnostics).into());}
 let hir=analysis.hir.ok_or("no hir")?;
 let mut runtime=RealtimeRuntime::new(&hir);
 if args.get(2).is_some_and(|s|s=="retained") {runtime.set_output_retention(OutputRetention::keep_confirmed_bars(16));}
 let seed_count=args.get(3).map_or(257,|s|s.parse::<usize>().unwrap());
 let seed:Vec<_>=(0..seed_count).map(|i|bar(i,0.25)).collect();
 runtime.seed_historical(&seed).map_err(|e|e.message)?;
 let mut replica=runtime.replica();
 let mut out=std::io::BufWriter::new(std::io::stdout().lock());
 out.write_all(b"{\"snapshot\":")?;out.write_all(&bytes(replica.result()))?;out.write_all(b",\"changes\":null}\n")?;
 for i in seed_count..seed_count+8 {
  for (offset,confirmed) in [(0.5,false),(-0.5,false),(0.25,false),(-0.25,true)] {
   let b=bar(i,offset);
   let changes=runtime.apply_update(if confirmed{BarUpdate::confirmed(b)}else{BarUpdate::forming(b)}).map_err(|e|e.message)?;
   replica.apply(&changes).map_err(|e|e.message)?;
   let snapshot=snapshot(&runtime);
   assert_eq!(snapshot,bytes(replica.result()),"replica mismatch at {i}/{offset}");
   out.write_all(b"{\"snapshot\":")?;out.write_all(&snapshot)?;out.write_all(b",\"changes\":")?;out.write_all(pine_runtime::public_runtime_changes_json(&changes).as_bytes())?;out.write_all(b"}\n")?;
  }
 }
 Ok(())
}

focused_benchmark.py.text:
"""18 related heap/timing cases, 3 alternating fresh processes per version.

This is a focused regression and cost measurement, not a new full-resource
qualification. No build takes place. Allocation figures are requested sizes
and exclude allocator overhead. Full result costs remain history-dependent.
"""
import argparse
import json
import math
from pathlib import Path
import statistics
import subprocess
from evidence_common import D, ROOT, sha, save, read, identity, directory, execute, finite, source, reject_nonfinite

def plan():
    cases=[]; scripts={}
    def add(name,body,bars,modes=('historical',),strategy=False):
        filename=name+'.pine'
        declaration=f'strategy("{name}", calc_on_order_fills=true)' if strategy else f'indicator("{name}")'
        scripts[filename]='//@version=6\n'+declaration+'\n'+body
        for mode in modes:
            cases.append({'name':name+'_'+mode,'script':filename,'bars':bars,'mode':mode,'repetitions':3})
    add('control_sma14','plot(ta.sma(close,14))\n',100000)
    add('control_rsi14','plot(ta.rsi(close,14))\n',100000)
    add('control_stdev512','plot(ta.stdev(close,512))\n',20000)
    for length in (5000,100000):
        add(f'clone_sma{length}',f'plot(ta.sma(close,{length}))\n',length+1000,('historical','retained'))
    add('checkpoint_sma5000','plot(ta.sma(close,5000))\n',6000,strategy=True)
    for function in ('wma','hma'):
        for length in (512,5000):
            add(f'ordinary_{function}{length}',f'plot(ta.{function}(close,{length}))\n',6000,('historical','retained'))
    add('ordinary_corr5000','plot(ta.correlation(close,high,5000))\n',6000,('historical','retained'))
    assert len(cases)==18
    return cases,scripts

def parse(case, raw):
    lines=raw.splitlines()
    if len(lines)!=1: raise ValueError('Expected one heap metrics JSON object')
    metrics=json.loads(lines[0],parse_constant=reject_nonfinite)
    if metrics.get('bars')!=case['bars'] or metrics.get('mode')!=case['mode']:
        raise ValueError('Heap mode or bars differ')
    required={'retainedHeapBytes'}
    if case['mode']=='historical':
        required|={'seedMs','seedAllocatedBytes','seedAllocations','rollingWindowValues','rollingWindowValueCapacity',
                   'cloneHeapBytes','cloneAllocations','cloneMedianMs','resultHeapBytes','resultMs'}
    else:
        required|={'applyUpdateMedianMs','updateMedianMs','applyAllocatedMedianBytes','updateAllocatedMedianBytes'}
    if not required<=metrics.keys(): raise ValueError('Missing heap metrics')
    for name,value in metrics.items():
        if isinstance(value,(int,float)) and not isinstance(value,bool):
            if not math.isfinite(value) or value<0: raise ValueError('Invalid metric '+name)
    return metrics

def summarize(cases, records):
    summary={}
    for case in cases:
        rows={tag:[r['metrics'] for r in records if r['case']==case['name'] and r['tag']==tag] for tag in ('before','after')}
        if any(len(v)!=3 for v in rows.values()): raise ValueError('Incomplete benchmark case')
        keys={k for k,v in rows['before'][0].items() if isinstance(v,(int,float)) and not isinstance(v,bool) and k!='bars'}
        for row in rows['before']+rows['after']:
            if keys!={k for k,v in row.items() if isinstance(v,(int,float)) and not isinstance(v,bool) and k!='bars'}:
                raise ValueError('Cannot summarize inconsistent metrics')
        metrics={}
        for key in sorted(keys):
            b=[r[key] for r in rows['before']]; a=[r[key] for r in rows['after']]
            bm,am=statistics.median(b),statistics.median(a)
            metrics[key]={'beforeSamples':b,'afterSamples':a,'beforeMedian':bm,'afterMedian':am,
                          'afterBeforeRatio':am/bm if bm else None}
        summary[case['name']]={'bars':case['bars'],'mode':case['mode'],'metrics':metrics}
    return summary

def quiescence():
    gates={}
    for tag in ('windows','linux'):
        exit_path=D/f'gate-{tag}.exit'
        if int(exit_path.read_text(encoding='utf-8-sig'))!=0: raise ValueError('Full production gate has not passed: '+tag)
        gates[tag]={'exitSha256':sha(exit_path),'logSha256':sha(D/f'gate-{tag}.log')}
    for name in ('ordinary-results.json','serialization-results.json'):
        if read(D/name)['status']!='passed': raise ValueError('Correctness must pass before timing: '+name)
    text=subprocess.check_output(['powershell.exe','-NoProfile','-Command',
        'Get-Process | Where-Object { $_.ProcessName -match "^(cargo|rustc|maturin|link|cl|msbuild|pine.*)$" } | Select-Object ProcessName,Id,CPU | ConvertTo-Json']).decode('utf8').strip()
    if text: raise ValueError('Compiler/probe processes remain active: '+text)
    return {'gates':gates,'ourCompilationValidationAndCorrectnessProcessesFinished':True,
            'matchingWindowsCompilerProcesses':[],
            'limitation':'Does not establish total OS or VM inactivity; caller must avoid concurrent Linux compilation.'}

def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--prepare-only',action='store_true')
    ap.add_argument('--timeout',type=float,default=300)
    args=ap.parse_args()
    cases,scripts=plan()
    sources={name:source(D/'bench-inputs'/name,text) for name,text in scripts.items()}
    if args.prepare_only:
        save(D/'benchmark-plan.json',{'cases':cases,'sources':sources,'plannedProcesses':108,'repetitionsPerVersion':3,'probesExecuted':False})
        print('Prepared focused 18 cases / 108 processes; no probes executed.',flush=True)
        return
    quiet=quiescence()
    identities={tag:identity('heap',tag) for tag in ('before','after')}
    out=directory('benchmark')
    receipt={'status':'running','method':'18 focused cases, 3 fresh processes per version, alternating before/after order',
             'plannedProcesses':108,'quiescence':quiet,'cases':cases,'sources':sources,'identities':identities,
             'runnerSha256':sha(Path(__file__)),'commonSha256':sha(D/'evidence_common.py'),
             'limits':['Descriptive medians, not worst-case or full resource qualification.',
                       'Heap probe requested allocation sizes exclude allocator overhead.',
                       'Retained mode holds public output at 64 confirmed bars; full mode materializes public history.',
                       'Metrics do not prove numerical correctness; separate independent math and ordinary byte comparisons do.'],
             'records':[]}
    try:
        for repetition in range(3):
            for case in cases:
                for tag in (('before','after') if repetition%2==0 else ('after','before')):
                    run,raw=execute(out,f'{case["name"]}-{tag}-{repetition}',
                          [identities[tag]['binary'],sources[case['script']]['path'],str(case['bars']),case['mode']],args.timeout)
                    row={'case':case['name'],'tag':tag,'repetition':repetition,'run':run}
                    receipt['records'].append(row); save(out/'progress.json',receipt)
                    if run['returncode']!=0: raise RuntimeError('Benchmark process failed: '+case['name'])
                    row['metrics']=parse(case,raw); save(out/'progress.json',receipt)
                    print(case['name'],tag,repetition,{k:v for k,v in row['metrics'].items() if k.endswith('Ms')},flush=True)
        for tag in identities:
            if identity('heap',tag)!=identities[tag]: raise ValueError('Heap identity changed')
        for entry in sources.values():
            if sha(Path(entry['path']))!=entry['sha256']: raise ValueError('Benchmark source changed')
        receipt.update(status='passed',completedProcesses=108,summary=summarize(cases,receipt['records']))
        save(out/'summary.json',receipt); save(D/'benchmark-results.json',receipt)
        print('PASS 18 focused cases / 108 processes',flush=True)
    except BaseException as error:
        receipt.update(status='failed',error=repr(error),completedProcesses=len(receipt['records']))
        save(out/'failure.json',receipt); save(out/'progress.json',receipt)
        raise

if __name__=='__main__':
    main()

numeric_compatibility.py.text:
"""Reuse exact prior final numeric receipts; execute 66 fresh current cases.

This preserves the prior qualified/unqualified boundary and proves unchanged
f64 output semantics, not a new complete floating-point error guarantee.
"""
import json
from pathlib import Path
import struct
from evidence_common import D, ROOT, identity, sha, read, save, directory, execute, snapshots, reject_nonfinite

def pairs(items):
    result={}
    for key,value in items:
        if key in result: raise ValueError('Duplicate JSON field: '+key)
        result[key]=value
    return result

def loads(raw):
    return json.loads(raw,parse_int=scalar_int,object_pairs_hook=pairs,parse_constant=reject_nonfinite)

def scalar_int(token):
    return -0.0 if token=='-0' else int(token)

def equal(a,b,path='$'):
    if isinstance(a,dict) and isinstance(b,dict):
        assert set(a)==set(b),path
        for key in a: equal(a[key],b[key],path+'.'+key)
    elif isinstance(a,list) and isinstance(b,list):
        assert len(a)==len(b),path
        for i,(x,y) in enumerate(zip(a,b)): equal(x,y,path+f'[{i}]')
    elif isinstance(a,(float,int)) and not isinstance(a,bool) and isinstance(b,(float,int)) and not isinstance(b,bool):
        if isinstance(a,int) and isinstance(b,int): assert a==b,(path,a,b)
        else: assert struct.pack('>d',float(a))==struct.pack('>d',float(b)),(path,a,b)
    else: assert type(a)==type(b) and a==b,(path,a,b)

def main():
    master=ROOT/'.local/numeric-tail-20261004/math-results-both.json'; prior=read(master)
    assert prior['status']=='passed'
    rows=[r for r in prior['records'] if r['tag']=='after']; assert len(rows)==66
    assert len({(r['case'],r['mode']) for r in rows})==66
    assert sum(r['analysis']['unqualifiedReason'] is None for r in rows)==62
    identities={tag:identity('differential',tag) for tag in ('before','after')}
    assert identities['before']['binarySha256']==prior['identities']['after']['binarySha256']
    out=directory('numeric-compatibility')
    receipt={'status':'running','plannedProcesses':66,'priorSummary':str(master),'priorSummarySha256':sha(master),
             'identities':identities,'runnerSha256':sha(Path(__file__)),
             'method':'66 fresh after cases compared f64 bits and structure to SHA-verified prior final after raw; intentional extreme-number lexical changes counted separately',
             'qualification':'Preserves previous 62 qualified and 4 unqualified cases. Does not improve unqualified numerical results.', 'records':[]}
    try:
        for i,old in enumerate(rows):
            script=Path(old['run']['command'][1]); source_sha=sha(script)
            entry=prior['sources'][old['case']]
            assert Path(entry['path']).resolve()==script.resolve()
            expected_source=entry['sha256']
            assert source_sha==expected_source
            assert old['run']['returncode']==0
            reference=Path(old['run']['stdout']); assert sha(reference)==old['run']['stdoutSha256']
            run,raw=execute(out,f'{i:02d}-after',[identities['after']['binary'],str(script),old['mode'],str(old['seedBars'])],300)
            row={k:old[k] for k in ('case','mode','seedBars')};row.update(run=run,priorStdout=str(reference),priorStdoutSha256=sha(reference),source=str(script),sourceSha256=source_sha)
            receipt['records'].append(row); save(out/'progress.json',receipt)
            assert run['returncode']==0
            snapshots(raw); expected=reference.read_bytes(); old_lines=expected.splitlines(); new_lines=raw.splitlines()
            snapshots(expected);assert len(old_lines)==len(new_lines)==33
            changed=0
            for b,a in zip(old_lines,new_lines):
                equal(loads(b),loads(a))
                changed+=b!=a
            row.update(sameNumericBitsAndStructure=True,sameBytes=expected==raw,lexicallyChangedSnapshots=changed,
                       priorMathAnalysis=old['analysis'],snapshots=33,changes=32)
            assert sha(script)==source_sha and sha(reference)==old['run']['stdoutSha256']
            save(out/'progress.json',receipt)
            print('Compared numeric',i+1,'/66',old['case'],old['mode'],'lexical snapshots',changed,flush=True)
        assert sha(master)==receipt['priorSummarySha256']
        for tag in identities: assert identity('differential',tag)==identities[tag]
        receipt.update(status='passed',completedProcesses=66,qualifiedProcesses=sum(r['priorMathAnalysis']['unqualifiedReason'] is None for r in receipt['records']),
                       sameBytesCases=sum(r['sameBytes'] for r in receipt['records']),lexicallyChangedCases=sum(not r['sameBytes'] for r in receipt['records']),
                       comparedSnapshots=2178,comparedChanges=2112)
        save(out/'summary.json',receipt);save(D/'numeric-compatibility-results.json',receipt)
    except BaseException as error:
        receipt.update(status='failed',error=repr(error));save(out/'failure.json',receipt);raise

if __name__=='__main__': main()

run_phase.py.text:
"""Bind a concrete validation/build/link invocation to frozen source before and after."""
from pathlib import Path
import json,sys,subprocess,time
from evidence_common import D,ROOT,sha,read,save

def verify():
    manifest=read(D/'source-identity.json')
    changed=[p for p,h in manifest['files'].items() if not (ROOT/p).is_file() or sha(ROOT/p)!=h]
    if changed: raise ValueError('Source changed: '+repr(changed))
    return {'manifestSha256':sha(D/'source-identity.json'),'archiveSha256':sha(D/'source.tar'),
            'files':len(manifest['files']),'sourceVerified':True}

def main():
    name=sys.argv[1];command=sys.argv[2:]; assert command
    before=verify(); entry={'phase':name,'command':command,'before':before,'startedUnixSeconds':time.time(),
                            'wrapperSha256':sha(Path(__file__)),'status':'running'}
    path=D/f'phase-{name}.json';assert not path.exists(),path
    save(path,entry)
    with (D/f'phase-{name}-wrapper.log').open('wb') as log:
        completed=subprocess.run(command,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT)
    entry.update(returncode=completed.returncode,finishedUnixSeconds=time.time(),
                 wrapperLogSha256=sha(D/f'phase-{name}-wrapper.log'))
    after=verify(); assert before==after
    entry.update(after=after,status='passed' if completed.returncode==0 else 'failed')
    if name.startswith('gate-'):
        (D/(name+'.exit')).write_text(str(completed.returncode),encoding='utf8')
        entry.update(gateLogSha256=sha(D/(name+'.log')),gateExitSha256=sha(D/(name+'.exit')))
    elif name=='release':
        entry.update(buildLogSha256=sha(D/'build-release.log'),buildExitSha256=sha(D/'build-release.exit'))
    elif name.startswith('link-'):
        _,probe,tag=name.split('-');entry.update(linkReceiptSha256=sha(D/f'identity-{probe}-{tag}.json'),
            linkLogSha256=sha(D/f'link-{probe}-{tag}.log'))
    save(path,entry); print(name,entry['status'],'frozen files',before['files'],flush=True)
    raise SystemExit(completed.returncode)

if __name__=='__main__':main()

