from pathlib import Path
import json
import serialization_runner as r
from evidence_common import directory, execute, save, sha, D
plan=r.prepare(); identity=r.identity('before');out=directory('calibration')
receipt={'status':'running','scope':'Three tiny baseline tooling preflights; excluded from performance/qualification counts',
         'identity':identity,'runnerSha256':sha(Path(__file__)),'records':[]}
try:
    for scenario in ('ordinary','extreme','records'):
        case={'scenario':scenario,'bars':6}
        run,raw=execute(out,scenario,[identity['binary'],scenario,'6',plan['source']['path'],str(out/scenario)],30)
        row={'case':case,'run':run};receipt['records'].append(row);save(out/'progress.json',receipt)
        assert run['returncode']==0,(scenario,run)
        row['metrics']=r.metrics(raw,case)
        row['rawJson']={kind:{'path':str(out/scenario/(kind+'.json')),'sha256':sha(out/scenario/(kind+'.json'))} for kind in ('full','delta')}
    receipt['status']='passed';save(out/'summary.json',receipt);save(D/'calibration-results.json',receipt)
    print('Three baseline tooling preflights passed; excluded from performance counts')
