'use strict';
// This probe is intentionally standalone: it loads the real generated Wasm
// module but never invokes Cargo, a build, or the performance probes.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

assert.equal(process.argv.length, 4, 'usage: node wasm_paged_probe.cjs <generated-module.js> <receipts-dir>');
const modulePath = path.resolve(process.argv[2]);
const out = path.resolve(process.argv[3]);
const source = '//@version=6\nindicator("paged Wasm windows")\nplot(ta.sma(close,257),title="sma257")\nplot(ta.sma(close,5000),title="sma5000")\nplot(ta.wma(close,5000),title="wma5000")\nplot(ta.hma(close,512),title="hma512")\n';
const seedQuarters = Array.from({ length: 5100 }, (_, index) => 400 + (index * 7) % 29);
const updates = [
  { method: 'applyForming', quarter: 431 },
  { method: 'applyForming', quarter: 405 },
  { method: 'applyForming', quarter: 424 },
  { method: 'applyConfirmed', quarter: 412 },
  { method: 'applyForming', quarter: 437 },
  { method: 'applyConfirmed', quarter: 408 },
];
const csv = quarters => ['time,open,high,low,close,volume', ...quarters.map((quarter, index) => {
  const value = quarter / 4;
  return `${index * 60000},${value},${value},${value},${value},1`;
}), ''].join('\n');
const hash = text => crypto.createHash('sha256').update(text).digest('hex');
const files = [];
const save = (name, contents) => {
  fs.writeFileSync(path.join(out, name), contents);
  files.push({ path: path.join(out, name), bytes: Buffer.byteLength(contents), sha256: hash(contents) });
};
save('program.pine', source);
save('seed.csv', csv(seedQuarters));
save('updates.json', JSON.stringify(updates, null, 2));
const bitView = new DataView(new ArrayBuffer(8));
const bits = value => { bitView.setFloat64(0, value); return bitView.getBigUint64(0); };
let finiteSmaBitChecks = 0;
let smaWarmupNullChecks = 0;
let batchCalls = 0;
let snapshotsCompared = 0;
let deltaApplications = 0;
let identicalRetransmissions = 0;
let confirmedStabilityChecks = 0;
const cases = [];
const assertSmas = (wire, quarters, label) => {
  const result = JSON.parse(wire);
  assert.equal(result.schemaVersion, 9);
  assert.equal(result.renderMetadataVersion, 1);
  assert.deepEqual(result.diagnostics, []);
  assert.equal(result.plots.length, 4);
  for (const [plot, length] of [[0, 257], [1, 5000]]) {
    const values = result.plots[plot].values;
    assert.equal(values.length, quarters.length);
    let integerSum = 0;
    for (let index = 0; index < quarters.length; index++) {
      integerSum += quarters[index];
      if (index >= length) integerSum -= quarters[index - length];
      assert.ok(Number.isSafeInteger(integerSum));
      if (index < length - 1) {
        assert.equal(values[index], null, `${label}: SMA ${length} warmup ${index}`);
        smaWarmupNullChecks++;
      } else {
        assert.equal(typeof values[index], 'number');
        const expected = integerSum / (4 * length);
        assert.equal(bits(values[index]), bits(expected), `${label}: SMA ${length} bits ${index}`);
        finiteSmaBitChecks++;
      }
    }
  }
};

let pine, program, session, consumer;
try {
  // require() synchronously instantiates the generated real WebAssembly.Module.
  pine = require(modulePath);
  const batch = quarters => {
    const freshProgram = pine.compileScript(source);
    batchCalls++;
    try { return freshProgram.runCsv(csv(quarters)); }
    finally { freshProgram.free(); }
  };
  const seedBatch = batch(seedQuarters);
  save('seed-batch.json', seedBatch);
  assertSmas(seedBatch, seedQuarters, 'seed batch');
  program = pine.compileScript(source);
  session = program.realtimeSession();
  const seedVisible = session.seed(csv(seedQuarters));
  save('seed-visible.json', seedVisible);
  assert.equal(seedVisible, seedBatch, 'seed borrowed snapshot versus fresh batch');
  snapshotsCompared++;
  assertSmas(seedVisible, seedQuarters, 'seed visible');
  consumer = session.replica();
  assert.equal(consumer.result(), seedVisible);
  let confirmedQuarters = seedQuarters.slice();
  let confirmedWire = session.confirmedResult();
  assert.equal(confirmedWire, seedVisible);
  for (const [index, update] of updates.entries()) {
    const stem = `update-${String(index).padStart(2, '0')}`;
    const price = update.quarter / 4;
    const bar = { time: confirmedQuarters.length * 60000, open: price, high: price, low: price, close: price, volume: 1 };
    const input = JSON.stringify(bar);
    save(`${stem}-input.json`, input);
    const changes = session[update.method](input);
    save(`${stem}-changes.json`, changes);
    assert.equal(JSON.parse(changes).visibility, update.method === 'applyConfirmed' ? 'confirmed' : 'preview');
    assert.equal(consumer.apply(changes), true);
    deltaApplications++;
    assert.equal(consumer.apply(changes), false);
    identicalRetransmissions++;
    const visibleQuarters = [...confirmedQuarters, update.quarter];
    const actual = session.result();
    const expected = batch(visibleQuarters);
    const replicated = consumer.result();
    const currentConfirmed = session.confirmedResult();
    save(`${stem}-batch.csv`, csv(visibleQuarters));
    save(`${stem}-visible.json`, actual);
    save(`${stem}-batch.json`, expected);
    save(`${stem}-replica.json`, replicated);
    save(`${stem}-confirmed.json`, currentConfirmed);
    assert.equal(actual, expected, `${stem}: borrowed snapshot versus fresh batch (includes WMA/HMA)`);
    assert.equal(replicated, actual, `${stem}: parsed changes replica`);
    snapshotsCompared++;
    assertSmas(actual, visibleQuarters, stem);
    if (update.method === 'applyConfirmed') {
      confirmedQuarters = visibleQuarters;
      confirmedWire = actual;
      assert.equal(currentConfirmed, actual, `${stem}: confirmed snapshot`);
    } else {
      assert.equal(currentConfirmed, confirmedWire, `${stem}: forming must preserve confirmed bytes`);
      confirmedStabilityChecks++;
    }
    cases.push({ index, method: update.method, visibleBars: visibleQuarters.length,
      snapshotSha256: hash(actual), batchSha256: hash(expected), changesSha256: hash(changes) });
  }
  const result = { status: 'passed', seedBars: seedQuarters.length, inputSourceSha256: hash(source),
    inputSeedSha256: hash(csv(seedQuarters)), finiteSmaBitChecks, smaWarmupNullChecks,
    batchCalls, snapshotsCompared, deltaApplications, identicalRetransmissions, confirmedStabilityChecks,
    mathematicalQualification: 'SMA257/SMA5000 independent exact integer-quarter sliding sum and f64 bit oracle',
    differentialQualification: 'WMA5000/HMA512 whole snapshots compared byte-for-byte to seven fresh compiled batch runs; not independent numeric oracles',
    cases, files };
  fs.writeFileSync(path.join(out, 'node-results.json'), JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result));
} catch (error) {
  fs.writeFileSync(path.join(out, 'node-failure.json'), JSON.stringify({ status: 'failed',
    message: String(error), stack: error.stack, cases, files, finiteSmaBitChecks,
    smaWarmupNullChecks, batchCalls, snapshotsCompared, deltaApplications,
    identicalRetransmissions, confirmedStabilityChecks }, null, 2));
  throw error;
} finally {
  if (consumer) consumer.free();
  if (session) session.free();
  if (program) program.free();
}
